#!/usr/bin/env python3
"""Summarize real ROS Noetic candidate-only ZED X RGBD+gyro fallback tests."""
import json,collections
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];base=ROOT/'outputs/zedx_rgbd_imu_fallback_20261020'
benchmark={}
for name in ['localization_gyro_fused_v2','localization_from2_gyro_fused_v2','localization_3_gyro_dense_v3','localization_3_visual_only_v2']:
 p=base/name/'metrics.json'
 if p.exists():benchmark[name]=json.load(open(p))
ros={}
for name in ['localization_3_no_lidar_dense_guarded_ros1','localization_from2_no_lidar_15s_ros1_20261020','localization_3_rgbd_no_imu_12s_retry']:
 p=base/name/'events.json'
 if not p.exists():continue
 j=json.load(open(p));x=j['odometry'];st=collections.Counter(z['text'].split()[0] for z in j['statuses']);ros[name]={'candidate_count':len(x),'state_counts':dict(st),'forbidden_pose':j.get('forbidden_pose_count',0)}
 if len(x)>1:
  t=np.asarray([z['stamp'] for z in x]);xyz=np.asarray([z['xyz'] for z in x]);dt=np.diff(t);ds=np.linalg.norm(np.diff(xyz,axis=0),axis=1)
  ros[name].update(candidate_range_s=float(t[-1]-t[0]),max_gap_s=float(dt.max()),max_step_m=float(ds.max()),max_pose_derived_speed_mps=float(np.max(ds/dt)))
seedname='localization_3_seeded_20to55_fixed_ros1'; p=base/seedname;se=json.load(open(p/'seeded_events.json'));sv=json.load(open(p/'vo_events.json'))
start_stamp=json.load(open(ROOT/'outputs/looooo_integrity_20261019/localization_3.json'))['sensor_timestamps']['lidar']['first_stamp']
traj=np.array([z['stamp']-start_stamp for z in se['odometry']]);xyz=np.array([z['xyz'] for z in se['odometry']]);dt=np.diff(traj);ds=np.linalg.norm(np.diff(xyz,axis=0),axis=1)
seed=dict(complete='COMPLETE' in (p/'status.txt').read_text(),replay_exit_zero='PLAY_EXIT=0' in (p/'status.txt').read_text(),total_seeded_odom_candidates=len(traj),candidate_start_sec=float(traj[0]),candidate_end_sec=float(traj[-1]),messages_during_outage=int(((traj>=20)&(traj<55)).sum()),messages_after_lidar_return=int((traj>=55).sum()),largest_candidate_step_m=float(ds.max()),largest_pose_derived_speed_mps=float(np.max(ds/dt)),forbidden_pose=int(se['forbidden_pose_count']),bridge_rejoin_review_required=any('LIDAR_RETURNED_REJOIN_REQUIRES_EXTERNAL_REVIEW' in x for x in se['states']),vision_candidate_count=len(sv['odometry']),vision_forbidden_pose=sv.get('forbidden_pose_count',0))
result={'offline_trajectories_not_surveyed_ground_truth':benchmark,'isolated_ros1_camera_only_runs':ros,'20to55s_seeded_outage_bridge':seed,'safety':'No real motion-control authority, no /pose or /aft_mapped_to_init replacement, independent physical calibration not verified, and simulated failure flag is not hardware health attestation'}
(base/'FINAL_FALLBACK_METRICS_20261020.json').write_text(json.dumps(result,indent=2)+'\n')
lines=['# GPS-/LiDAR-independent ZED X RGB-D + gyro local odometry: offline validation', '', '## Model / nomenclature', '', 'This is **metric RGB-D visual odometry (VO)** from KLT-tracked image corners, registered ZED stereo depth and 2D–3D PnP/RANSAC, with short-interval ZED gyro rotation integration. It is NOT a full tightly coupled visual–inertial filter: there is no accelerometer gravity/bias optimization, full IMU preintegration, bundle adjustment, loop closure, or estimator covariance. It is not a replacement FAST-LIVO2 ESIKF.', '', 'The ZED stereo engine provides registered depth. This experiment requires camera RGB, ZED depth, and ZED IMU; it never consumes LiDAR scans, LiDAR map, GPS or saved FAST odometry to compute VO. Saved LiDAR-only odometry is used **only after estimation** for comparison and before the simulated dropout as an explicitly separate candidate-frame seed.', '', '## Offline LiDAR-IMU odometry proxy comparisons', '', '| Bag / mode | Frames processed | Accepted fraction | Disagreement at 55s (or requested window end) | Outage comparison RMSE |', '|---|---:|---:|---:|---:|']
for name,m in benchmark.items():
 lines.append(f"| {name} | {m['frames_processed']} | {100*m['vision_good_fraction']:.1f}% | {m['outage_end_error_to_lio_proxy_m']:.2f}m | {m['outage_position_error_vs_lio_proxy_rmse_m']:.2f}m |")
lines+=['','All reported position differences are **relative to LiDAR-only odometry after alignment at dropout onset**. The LiDAR-only estimate is NOT surveyed ground truth and shares uncertain camera/body calibration. These figures are NOT absolute positioning accuracy.', '', '## Real isolated ROS1 bag candidates', '', '| Offline replay | Candidate messages | Camera-only gyro mode | Safety |', '|---|---:|---|---|']
for name,m in ros.items():
 lines.append(f"| {name} | {m['candidate_count']} | {'gyro present' if m['candidate_count'] else 'gyro absent'} | zero /pose: {m['forbidden_pose']==0} |")
lines+=['', 'ZED RGB-D without IMU was deliberately withheld because `require_imu_for_healthy=true`. That conservative policy should remain for unattended cart failover, unless an independently reviewed VO-only degraded state is added. Camera blackout and long pose-publication gap also cause untrusted/re-arm states, not fabricated inertial translation.', '', '## Complete 20–55-second simulated LiDAR outage, independent ROS1 master', '',f"- Candidate frame seeded from PRE-OUTAGE healthy FAST odometry; **{seed['total_seeded_odom_candidates']}** continuous candidate samples between **{seed['candidate_start_sec']:.2f}s and {seed['candidate_end_sec']:.2f}s** (all during the simulated 20–55s interval).",f"- Largest candidate position step **{seed['largest_candidate_step_m']:.3f}m**, maximum candidate pose-derived speed **{seed['largest_pose_derived_speed_mps']:.2f}m/s**.",f"- On simulated LiDAR return after 55s: **{seed['messages_after_lidar_return']}** further continuation candidates; terminal bridge status `LIDAR_RETURNED_REJOIN_REQUIRES_EXTERNAL_REVIEW` = **{seed['bridge_rejoin_review_required']}**.",f"- Camera/gyro frontend emitted **{seed['vision_candidate_count']}** standalone candidate updates; seeded bridge never published /pose (count **{seed['forbidden_pose']}**).", '- This is an intentionally simulated outage flag, NOT a real detector of LiDAR physical failure, collision safety, wheel odometry, or live brake command. The camera odometry is NOT used as a FAST-LIVO2 estimator update and no autonomous switch to /aft_mapped_to_init occurs.', '', '## Architecture for the real golf cart', '', '1. In healthy mode, keep FAST-LIVO2 as local odometry. Concurrently run ZED X RGB-D + gyro candidate-only, with a common synchronized sensor clock and a physically verified body-camera extrinsic.', '2. Use PRE-FAILURE common timestamps to align `T_fast_odom <- T_camera_odom`. Once independent health detection confirms failure, freeze the anchor, and use only fresh visually verified increments; never depend on unavailable LiDAR scans.', '3. Give local planning a deliberate DEGRADED/STOPPING state, with speed limit/braking logic implemented in verified vehicle control. Publishing a fallback Odometry message alone does not establish safe navigation.', '4. On LiDAR return, require stationary sensor reinitialization and map-epoch rejoin review; **do not automatically combine** the new LiDAR pose with accumulated camera drift or enable global /pose.', '5. A proper VIO upgrade should test stereo-inertial OpenVINS / VINS-Fusion / Basalt / Kimera-VIO against these SAME bags, using measured camera-IMU extrinsics and timestamps. Only replace the lightweight RGB-D VO if it demonstrably improves failure duration, runtime and motion error.', '', '## Reproduce', '', '```bash', 'cd ~/Desktop/ALIVE_N/FailSafe_FastLivo2', 'python3 scripts/test_zedx_rgbd_imu_odom_core.py', 'bash -n scripts/run_zedx_seeded_lidar_outage_ros1.sh', 'roslaunch --nodes launch/fresh_zedx_rgbd_imu_candidate_offline.launch', '# WARNING: following scripts replay saved bags in independent offline Docker ROS1 masters:', 'RUN=<new_id> ./scripts/run_zedx_camera_imu_no_lidar_rosbag.sh localization_3', 'RUN=<new_id> ./scripts/run_zedx_seeded_lidar_outage_ros1.sh localization_3', '```', '', '**NO-GO for live odometry authority or autonomous LiDAR-failure navigation** until physical extrinsics, sensor-clock synchronization, independent speed/brake controls, and benchmarked reliability are verified.']
(base/'FINAL_FALLBACK_REPORT_20261020.md').write_text('\n'.join(lines)+'\n')
print('Seeded bridge',seed,'\nreport',base/'FINAL_FALLBACK_REPORT_20261020.md')
